\caption{Polar Encoder}
\label{algo:slow-encoder}
\begin{algorithmic}[1]
	\Const{$M \in \F_q^{k \x k}, S \subseteq [n], \bvec{\alpha} \in \F_q^{S^c}$}
	\Require{$\bvec{U} \in \F_q^S$}
	\Ensure{$\bvec{Z} \in \F_q^n$}
	\Procedure{Polar-Encoder}{$\bvec{U}; \bvec{\alpha}$}
	\State{Extend $\bvec{U}$ to $\bar{\bvec{U}} \in \F_q^n$
		by letting $(\bar{\bvec{U}}_i)_{i \not \in S} = \bvec{\alpha}$
		for coordinates not in $S$}
	\State \Return{$\bvec{Z} = \bar{\bvec{U}}\cdot (M^{-1})^{\otimes t}$}
	\EndProcedure
\end{algorithmic}

\caption{Fast Polar Encoder}
\label{algo:fast-encoder}
\begin{algorithmic}[1]
	\Const{$M \in \F_q^{k \x k}$}
	\Require{$\bvec{\bar U} \in (\F_q^k)^{\otimes t}$}
	\Ensure{$\bvec{Z}  = \bvec{\bar U} \cdot (M^{-1})^{\otimes t}$}
	\Procedure{Fast-Polar-Encoder$_t$}{$\bvec{\bar U}$}
	\If{$t=0$} 
	\State \Return $\bvec{\bar U}$ 
	\EndIf
	\ForAll{$j \in [k]$}
	\State{$\bvec{Z}^{(j)} \gets$ \Call{Fast-Polar-Encoder$_{t-1}$}{$\bar{\bvec{U}}_{[\cdot, j]}$}}
	\EndFor
	\ForAll{$\bvec{i} \in [k]^{t-1}$}
	\State
	$\bvec{Z}_{[\bvec{i}, \cdot]} \gets  (
	\bvec{Z}^{(1)}_{\bvec{i}},
	\bvec{Z}^{(2)}_{\bvec{i}},
	\dots,
	\bvec{Z}^{(k)}_{\bvec{i}}
	)\cdot M^{-1}$
	\EndFor
	\State \Return $\bvec Z$
	\EndProcedure
\end{algorithmic}

\caption{Successive-Cancellation Decoder}
