\label{def:fl}
A floating point number system $F\subset \R$ is a subset of real numbers whose elements have the form
\[ y = \pm a\cdot \beta^{e-\Delta},\]
where
\begin{itemize}
    \item The integer $\beta\ge 2$ is the {\em base} or {\em radix}
    \item The natural number $\Delta$ is the {\em precision}
    \item The integer $e$ is the {\em exponent} and has the range $e_{\min}\le e\le e_{\max}$ for integers $e_{\min}\le e_{\max}$
    \item The natural number $a$ is the {\em significand} and it is assumed that
    \[\beta^{\Delta-1}\le a \le \beta^{\Delta}-1.\]
\end{itemize}

The {\em representation range} of $F$ is given by $\brackets{\beta^{e_{\min}-1},\beta^{e_{\max}}\parens{1-\beta^{-\Delta}} }$.

\label{def:fl-simple}
We use the floating point number system from \cref{def:fl} with the following simplifications/modifications:
\begin{itemize}
    \item Set $\beta=2$.
    \item $\Delta=\ell$.\footnote{Since we are using $\ell$ {\em bits} to represent $a$.}
    \item $e_{\min}=-2^{\ell}$ and $e_{\max}=2^\ell$.
\end{itemize}

\label{def:roundoff}
The {\em unit roundoff} is defined as
\[u = 2^{-\Delta}.\]

\label{lem:rounding-error}
Let $x\in\mathbb{R}$ be in the representation range of the floating point system. Then
\[\rnd{x}=(1+\delta)\cdot x\text{    where    } \abs{\delta}<u.\]

    \label{lem:rational-fn-error}
Let $f(X_1,\dots,X_N)$ and $g(X_1,\dots,X_N)$ be {\em multi-linear} polynomials\footnote{The result can be proven for general polynomials as well. However, since we only need the result for multilinear polynomials and the notation for multi-linear polynomials is slightly cleaner, we stick with the multi-linear case.} such that both satisfy the following properties:
\begin{itemize}
    \item the degree is at most $d$
    \item there are at most $m$ monomials
    \item all the coefficients are non-negative and have exact representation in the floating point number system.
\end{itemize}
Further, let $\bvec{x},\tvec{x}\in\R_{\ge 0}^N$, be such that there exists an $\eps>0$ such that for every $i\in [N]$, we have
\[ \abs{\bvec{x}_i-\tvec{x}_i}\le \eps \bvec{x}_i,\]
and moreover let $e_0$ be such that all $\tvec{x}_i$  and all coefficients of $f, g$ lie in $\brackets{2^{-e_0}, 2^{e_0}}$.
Then, assuming 
\begin{eqnarray}
    \label{eq:accuracy-pre-bound}
    4\parens{d\cdot \eps + (d+\log{m})\cdot u}+1& \le&  \frac 12, \\
\label{eq:range-pre-bound}
    e_1 := 2 (d+1)(e_0 + 1) + 4 \log m + 1  & \leq & 2^\ell,
\end{eqnarray}
we have that
\begin{equation}
    \label{eq:final-rational-fn-bound}
    \abs{\frac{f(\bvec{x})}{g(\bvec{x})} - \rnd{\frac{f(\tvec{x})}{g(\tvec{x})} } } 
\le 8 \cdot \parens{d\cdot \eps + (d+\log{m}+1)\cdot u} \cdot \frac{f(\bvec{x})}{g(\bvec{x})},
\end{equation}
 and moreover
\begin{equation}
\label{eq:range-post-bound}
    \left|\log \rnd{\frac{f(\tvec{x})}{g(\tvec{x})}}\right| \leq e_1,
\end{equation}

where the $\rnd{\frac{f(\tvec{x})}{g(\tvec{x})} }$ is computed by using pair-wise operations (and paying for approximation error for each such operation as in the standard model).

